const {chromium}=require('playwright');const F='file://'+process.argv[2];const S=process.argv[3];
const ok=(c,m)=>console.log((c?'PASS ':'FAIL ')+m);
const say=async(p,t)=>{const n=await p.locator('.m-ai').count();await p.fill('#chat-in',t);await p.press('#chat-in','Enter');await p.waitForFunction(k=>document.querySelectorAll('.m-ai').length>k,n,{timeout:15000});};
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1440,height:950}});const e=[];p.on('pageerror',x=>e.push(x.message));
await p.goto(F);await p.evaluate(()=>localStorage.clear());await p.reload();await p.click('.lp-hero [data-act="new"]');
await p.fill('#start-in','We want one-tap reorder to increase repeat purchases by 40%. Support tickets show customers rebuild baskets by hand.');await p.press('#start-in','Enter');
await p.waitForSelector('.m-ai .pcard');await p.click('[data-acceptall]');
await say(p,'What are the biggest risks?');
const last=()=>p.locator('.m-ai').last();
ok((await last().textContent()).includes('Risks from the definition'),'answers a risk question instead of the script');
ok((await last().locator('.qcard b').textContent()).startsWith('Back to this'),'then returns to the pending question');
await say(p,'Show me a forecast chart for this feature.');
ok(await last().locator('.viz svg').count()>=1,'forecast draws a chart');
ok(await last().getByText('Placeholders · add numbers').count()>=1,'no data means placeholders, not invented numbers');
ok(await last().getByText('Assumptions to test first').count()===1,'also suggests an assumption matrix from the definition');
await last().locator('[data-vtoggle]').first().click();
await p.locator('input[data-vedit]').first().fill('120');await p.locator('input[data-vedit]').first().press('Tab');await p.waitForTimeout(200);
ok(await p.locator('.m-ai').last().getByText('From your numbers').count()>=1,'typing numbers turns it into your data');
await say(p,'Market size according to the Gartner report: 2025: 12, 2026: 15, 2027: 19, 2028: 24');
ok(await last().getByText('Your figures over time').count()===1,'pasted figures become a chart');
ok(await last().getByText('Source: Named in your message').count()===1,'credits the source you named');
await p.screenshot({path:S+'/dyn-chat.png'});
await last().locator('.vcard button.yes').first().click();
ok(await p.locator('.docpane .vitem svg').count()===1,'accepted chart appears in the definition');
await say(p,'How should I pitch this to my VP?');ok((await last().textContent()).includes('Lead with the problem'),'pitch question answered');
await p.locator('.dock .chip',{hasText:'Market'}).click();await p.waitForFunction(()=>document.querySelector('.m-ai:last-of-type'));await p.waitForTimeout(900);
ok(await last().getByText('Market size: total, serviceable, obtainable').count()===1,'Market chip gives a TAM/SAM/SOM frame');
await p.screenshot({path:S+'/dyn-chat2.png'});
// Claude mode with an estimate
const q=await b.newPage({viewport:{width:1440,height:950}});q.on('pageerror',x=>e.push(x.message));
await q.addInitScript(()=>{const out={reply:"Rough market estimates from training data. Verify before use.",questions:[],proposals:[{kind:"visual",text:"Grocery reorder market (estimate)",visual:{type:"bar",unit:"$bn",basis:"estimate",source:"Claude training knowledge, not verified",series:[{name:"Size",points:[{x:"TAM",y:50},{x:"SAM",y:8},{x:"SOM",y:null}]}]}},{kind:"visual",text:"broken",visual:{type:"line",series:[]}}]};
 window.claude={use:async n=>{if(n!=="sample")return null;const f=async()=>({text:""});f.json=async()=>out;return f;}};});
await q.goto(F);await q.evaluate(()=>localStorage.clear());await q.reload();await q.waitForTimeout(300);await q.click('.lp-hero [data-act="new"]');
await q.fill('#start-in','What is the market size for grocery reorder?');await q.press('#start-in','Enter');await q.waitForSelector('.vcard');
ok(await q.getByText('Unverified estimate · check before use').count()===1,'Claude estimates are labelled unverified');
ok(await q.locator('.vcard').count()===1,'malformed charts are dropped');
await q.screenshot({path:S+'/dyn-claude.png'});
ok(e.length===0,'no errors '+e.join('; '));await b.close();})();
